+/** Theoretical vs actual item use between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const round3 = (n) => Math.round(n * 1000) / 1000;
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = getDish(store, s.dishId);
+    const recipe = getRecipe(store, dish.recipeId);
+    for (const n of scaled(recipe, s.qty)) {
+      theoretical.set(n.itemId, round3((theoretical.get(n.itemId) ?? 0) + n.qty));
+    }
+  }
+  const actual = new Map();
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    actual.set(itemId, round3((actual.get(itemId) ?? 0) + m.qty));
+  }
+  const ids = [...new Set([...theoretical.keys(), ...actual.keys()])].sort((a, b) => a - b);
+  return ids
+    .map((itemId) => {
+      const theo = theoretical.get(itemId) ?? 0;
+      const act = actual.get(itemId) ?? 0;
+      const item = store.data.items.find((i) => i.id === itemId);
+      return { itemId, name: item?.name ?? "", theoretical: theo, actual: act, diff: round3(act - theo) };
+    })
+    .filter((r) => r.theoretical > 0 || r.actual > 0);
+}
